def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    units_available = int(supply // WATER_REQ)
    if units_available < 0:
        units_available = 0

    highest_prev_bid = 0.0
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 120:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None and bid > highest_prev_bid:
                highest_prev_bid = bid

    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    if not alive_opponents:
        return float(min(budget, 18.0 if not my_urgent else 55.0))

    if units_available >= 2:
        base = 16.0
        if highest_prev_bid > 0:
            base = min(42.0, max(base, highest_prev_bid * 0.28))
        if my_urgent:
            base = max(base, 38.0)
        if very_urgent:
            base = max(base, 58.0)
        if day >= 8 and budget > 200:
            base += 4.0
        return float(min(budget, base))

    base = 52.0
    if highest_prev_bid >= 120:
        base = 66.0
    elif highest_prev_bid >= 90:
        base = 61.0
    elif highest_prev_bid >= 60:
        base = 57.0

    if urgent_opp >= 2:
        base += 4.0
    elif urgent_opp == 0 and rich_opp >= 2:
        base -= 3.0

    if my_urgent:
        base = max(base, 68.0)
    if very_urgent:
        base = max(base, 90.0)

    if day >= 9:
        base += 6.0

    if budget < base:
        if my_urgent:
            return float(budget)
        return float(min(budget, 35.0))

    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids for immediate reaction
    yesterday_bids = []
    highest_prev_bid = 0.0
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
                yesterday_bids.append(b)
                if b > highest_prev_bid:
                    highest_prev_bid = b
            except Exception:
                pass

    # Baseline bid based on my urgency
    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.95
    elif my_hp <= 3 or my_no_water_days == 1:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # If someone was strongly pressuring yesterday, undercut slightly
    # Cindy's behavior suggests a ceiling; we try to beat everyone except the top bidder.
    # Use a small margin to avoid overpaying.
    if highest_prev_bid > 0:
        # Convert supply to a rough need factor: more supply => lower bid pressure
        # Use explicit int for any indexing-like operations (none here), but keep safe math.
        need_factor = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
        need_factor = max(0.0, min(1.0, need_factor))

        # Target slightly below the highest previous bid if I'm not in critical HP.
        # If I'm critical, prioritize securing water.
        if my_hp > 3:
            target = min(my_budget, max(base, highest_prev_bid * 0.93 - 2.0))
        else:
            target = min(my_budget, max(base, highest_prev_bid * 0.98 + 1.0))

        # Clamp to reasonable range relative to supply and my budget
        # Higher supply reduces need; lower supply increases it.
        supply_pressure = 0.35 + 0.65 * need_factor
        target = min(target, my_budget, DAILY_SALARY * (0.35 + 0.9 * supply_pressure))
        return max(0.0, target)

    # Fallback if no usable yesterday bids
    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.9)
    return min(my_budget, base)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_players = len(alive_opponents) + 1

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 40

    if supply / num_players < WATER_REQ:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    return min(my_status['budget'], max(DAILY_SALARY * 0.5, avg_prev_bid * 1.05))
